trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

final case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(kvs: (String, Any)*): Token = copy(metadata = metadata ++ kvs)
}

object Token {
  def toToken(value: Any, tokenType: TokenType = TokenType.STRING, metadata: Map[String, Any] = Map.empty): Token =
