final class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: Vector[T => Option[Token]] = Vector.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry = registry.updated(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers = handlers :+ handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.toList.map { item =>
          handlers.view
            .map(handler => handler(item))
            .collectFirst { case Some(token) => token }
        }
    }
  }
}

