class TokenFunctor[+T](private val value: T) {
  def map[B](func: T => B): TokenFunctor[B] = new TokenFunctor(func(value))

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] = func(value)

  def getOrElse(default: => T): T = if (value == null) default else value

  def get: T = value
}

final class TokenMonad[+T](value: T) extends TokenFunctor[T](value) {
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get(value))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    if (path.trim.isEmpty) return Some(tokenize(value))

    def step(current: Json, part: String): Option[Json] = {
      current.asObject.flatMap(_.apply(part))
        .orElse(current.asArray.flatMap { arr =>
          part.toIntOption.flatMap(arr.lift)
        })
    }

    val resolved = path.split("\\.").foldLeft(Option(value)) { (cur, part) =>
      cur.flatMap(step(_, part))
    }

    resolved.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def trimPunctuation(word: String): String = {
    val leftTrimmed = word.dropWhile(punctuation.contains)
    leftTrimmed.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) trimPunctuation(word) else word
    val lowered = if (lowercase) stripped.toLowerCase else stripped
    val lengthChecked = maxLength match {
      case Some(max) if lowered.length > max => lowered.take(max)
      case _ => lowered
    }

    if (lengthChecked.length < minLength) None
    else if (lengthChecked.isEmpty) None
    else Some(lengthChecked)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)

    words.zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> idx, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] private (
    normalizers: Vector[String => String],
    validators: Vector[T => Boolean],
    metadata: Map[String, Any]
) {

  def this() = this(Vector.empty, Vector.empty, Map.empty)

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(kvs: (String, Any)*): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators, metadata ++ kvs)

  def build(): T => Token = { value =>
    validators.foreach { validator =>
      require(validator(value), s"Validation failed for $value")
    }

    val normalized = normalizers.foldLeft(value.toString) { (current, normalizer) =>
      normalizer(current)
    }

    Token(normalized, TokenType.STRING, metadata)
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

